
.sheet {
  width: 100%;
  max-width: 640px;
  margin: 0 auto;
  background: linear-gradient(165deg, rgba(255, 253, 248, 0.94) 0%, rgba(250, 245, 235, 0.9) 100%);
  backdrop-filter: var(--glass);
  -webkit-backdrop-filter: var(--glass);
  border: 1px solid rgba(255, 255, 255, 0.9);
  border-radius: 22px;
  box-shadow:
    var(--lift-hi),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
  color: var(--c-text);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  overflow: hidden;
}

/* ── 顶部 ── */
.sheet__head {
  padding: 24px 26px 18px;
  border-bottom: 1px solid var(--c-border);
}

.sheet__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.sheet__title {
  font-size: 1.9rem;
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1.1;
  color: var(--c-text);
}

.sheet__sub {
  margin-top: 6px;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--c-text-muted);
  letter-spacing: 0.005em;
}

.sheet__font {
  display: flex;
  gap: 3px;
  flex-shrink: 0;
  padding-top: 4px;
}

.sheet__fontbtn {
  padding: 5px 10px;
  border: none;
  border-radius: 7px;
  background: rgba(120, 104, 78, 0.07);
  color: var(--c-text-faint);
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 550;
  cursor: pointer;
  transition:
    background 0.2s ease,
    color 0.2s ease;
  -webkit-tap-highlight-color: transparent;

  &:hover {
    color: var(--c-text);
  }
}

.sheet__fontbtn--on {
  background: var(--c-text);
  color: #fffdf9;
}

.steps {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 18px;
}

.steps__dot {
  width: 30px;
  height: 2.5px;
  border-radius: 2px;
  background: rgba(96, 84, 62, 0.16);
  transition: background 0.4s var(--ease);
}

.steps__dot--on {
  background: var(--c-text);
}

.steps__num {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--c-text-faint);
  letter-spacing: 0.02em;
}

/* ── 表单 ── */
.form {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 20px 26px 22px;
}

.page {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.row2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.split3 {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 10px;
}

/* ── 字段 ── */
.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.field__label {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--c-text-faint);
}

.field__input {
  width: 100%;
  padding: 11px 13px;
  background: var(--c-surface-sunken);
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  color: var(--c-text);
  font-family: var(--font-ui);
  font-size: 0.86rem;
  font-weight: 500;
  line-height: 1.5;
  outline: none;
  transition:
    background 0.2s var(--ease),
    border-color 0.2s var(--ease),
    box-shadow 0.2s var(--ease);

  &::placeholder {
    color: var(--c-text-faint);
    font-weight: 400;
  }

  &:hover {
    background: rgba(120, 104, 78, 0.075);
  }

  &:focus {
    background: var(--c-surface-raised);
    border-color: rgba(0, 113, 227, 0.5);
    box-shadow: 0 0 0 3.5px rgba(0, 113, 227, 0.1);
  }
}

.field__input--area {
  resize: vertical;
  min-height: 64px;
  font-family: var(--font-ui);
  line-height: 1.7;
}

/* ── 带单位的小格 ── */
.cell {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.cell--narrow {
  max-width: 138px;
}

.cell__in {
  flex: 1;
  min-width: 0;
  text-align: center;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
  font-weight: 600;
}

.cell__in--mono {
  letter-spacing: 0.06em;
}

.cell__unit {
  flex-shrink: 0;
  font-size: 0.74rem;
  font-weight: 550;
  color: var(--c-text-faint);
}

.cell__unit--mono {
  font-family: var(--font-mono);
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--c-text-muted);
}

/* ── 分组 ── */
.group {
  padding-top: 18px;
  border-top: 1px solid var(--c-border);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.group--top {
  padding-top: 0;
  border-top: none;
}

.group__h {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--c-text);
}

.group__desc {
  font-size: 0.76rem;
  font-weight: 500;
  color: var(--c-text-faint);
  line-height: 1.7;
}

.group__note {
  font-size: 0.76rem;
  font-weight: 500;
  color: var(--c-text-faint);
  line-height: 1.7;
}

.group__warn {
  color: var(--c-warning);
  font-weight: 600;
}

/* ── 财务三卡 ── */
.money {
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 15px 16px;
  border-radius: var(--radius);
  background: rgba(120, 104, 78, 0.045);
  border: 1px solid var(--c-border);
}

.money__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.money__k {
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--c-text);
  letter-spacing: 0.05em;
  flex-shrink: 0;
}

.money__ctrl {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.money__unit {
  font-family: var(--font-mono);
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--c-text-faint);
  flex-shrink: 0;
}

.money__num,
.money__cycle,
.money__note {
  background: var(--c-surface-raised);
  border: 1px solid transparent;

  &:hover {
    background: var(--c-surface-raised);
  }

  &:focus {
    border-color: rgba(0, 113, 227, 0.5);
    box-shadow: 0 0 0 3.5px rgba(0, 113, 227, 0.1);
  }
}

.money__num {
  width: 128px;
  text-align: right;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  padding: 8px 11px;
  font-size: 0.86rem;
}

.money__cycle {
  width: 84px;
  padding: 8px 6px;
  font-size: 0.78rem;
  font-weight: 550;
  font-family: var(--font-ui);
  color: var(--c-text-muted);
  appearance: none;
  text-align: center;
  cursor: pointer;
}

.money__cny {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 500;
  color: var(--c-text-faint);
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.money__note {
  font-size: 0.8rem;
  padding: 9px 11px;
}

/* ── 错误与导航 ── */
.err {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--c-danger);
  padding-top: 2px;
}

.nav {
  display: flex;
  gap: 10px;
  margin-top: 8px;
}

.nav__btn {
  flex: 1;
  padding: 13px;
  border-radius: 12px;
  font-family: var(--font-ui);
  font-size: 0.86rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition:
    background 0.2s var(--ease),
    color 0.2s var(--ease),
    border-color 0.2s var(--ease),
    opacity 0.2s var(--ease);
}

.nav__btn--main {
  border: 1px solid transparent;
  background: var(--c-text);
  color: #fffdf9;

  &:hover:not(:disabled) {
    background: #000;
  }

  &:active:not(:disabled) {
    opacity: 0.82;
  }

  &:disabled {
    opacity: 0.32;
    cursor: default;
  }
}

.nav__btn--ghost {
  flex: 0 0 112px;
  border: 1px solid var(--c-border-strong);
  background: transparent;
  color: var(--c-text-muted);

  &:hover:not(:disabled) {
    background: rgba(120, 104, 78, 0.05);
    color: var(--c-text);
  }

  &:disabled {
    opacity: 0.35;
    cursor: default;
  }
}

@media (max-width: 520px) {
  .row2 {
    grid-template-columns: 1fr;
  }

  .sheet__head {
    padding: 20px 18px 15px;
  }

  .form {
    padding: 18px 18px 20px;
  }

  .money__head {
    flex-direction: column;
    align-items: stretch;
  }

  .money__num {
    flex: 1;
    width: auto;
  }
}
